struct Payload {};

// C++17 Guaranteed Elision (Prvalue return)
Payload create_payload() {
    // Temporary object is constructed directly
    // in the caller's target object.
    return Payload{};
}

// Traditional Named RVO (NRVO) Candidate
Payload process_payload() {
    Payload local_result;
    // ... complex initialization
    // Compiler typically elides the copy/move here.
    return local_result;
}

// Case where NRVO is inhibited (conditional return)
// Requires copy/move pre-C++17 standard rules.
Payload combine(bool flag) {
    Payload p1, p2;
    if (flag) return p1;
    return p2;
}
